proposed.setup:
var A = window.ARC = window.ARC || {};
if (!A.esc) A.esc = function (v) { return String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); };
if (!A.uid) { var seq = 0; A.uid = function (p) { seq += 1; return String(p || 'x') + '-' + seq; }; }
if (!A.state || !A.state.users) A.state = JSON.parse(JSON.stringify(window.SEED));
if (!A.save) A.save = function () {};
if (!A.render) A.render = function () {};
if (!A.navigate) A.navigate = function () {};
if (!A.notify) A.notify = function () {};
if (!A.openDialog) A.openDialog = function () {};
if (!A.closeDialog) A.closeDialog = function () {};
if (!A.openPopover) A.openPopover = function () {};
if (!A.closePopover) A.closePopover = function () {};
if (!A.combobox) A.combobox = function () { return ''; };
if (!A.currentUser) A.currentUser = function () { var s = A.state; return s.session ? (s.users.filter(function (u) { return u.id === s.session; })[0] || null) : null; };
A.state.session = 'u-alice';

proposed.precondition:
var s = ARC.state;
assert.strictEqual(s.session, 'u-alice', 'signed in as alice-dev');
assert.ok(s.repositories.some(function (r) { return r.id === 'r-acme-docs' && r.ownerType === 'user' && r.ownerId === 'u-alice' && r.visibility === 'Public'; }), 'a public personal repository owned by the signed-in user');
assert.ok(s.files.some(function (f) { return f.repoId === 'r-acme-docs' && f.branch === 'main' && f.path === 'src/search.ts'; }), 'src/search.ts exists on main, so src is an existing directory on that branch');
assert.ok(!s.files.some(function (f) { return f.repoId === 'r-acme-docs' && f.branch === 'main' && f.path === 'src'; }), 'no file named src exists on main yet');

proposed.check:
var filesMain = function (p) { return ARC.state.files.filter(function (f) { return f.repoId === 'r-acme-docs' && f.branch === 'main' && f.path === p; }).length; };
var commitsMain = function () { return ARC.state.commits.filter(function (c) { return c.repoId === 'r-acme-docs' && c.branch === 'main'; }).length; };
saveFile({ el: { dataset: { repo: 'r-acme-docs', branch: 'main', path: '' } }, form: { 'fe-name': 'pw-file-control.md', 'fe-contents': 'control content', 'fe-message': 'Add pw-file-control.md' } });
assert.strictEqual(filesMain('pw-file-control.md'), 1, 'control: a valid unique path still creates a file');
var before = commitsMain();
saveFile({ el: { dataset: { repo: 'r-acme-docs', branch: 'main', path: '' } }, form: { 'fe-name': 'src', 'fe-contents': 'must not be saved', 'fe-message': 'Add src' } });
assert.strictEqual(filesMain('src'), 0, 'a file path conflicting with the existing src/ directory must be rejected as an invalid path');
assert.strictEqual(commitsMain(), before, 'the rejected submission must not add a commit');

